int register_genl_family(struct genl_family *family)
{
    int err;

    if (!family || !family->ops)
        return -EINVAL;

    if (family->name[0] == '\0')
        return -EINVAL;

    mutex_lock(&genl_mutex);

    if (genl_find_family(family->name)) {
        err = -EEXIST;
        goto out_unlock;
    }

    if (family->id == GENL_ID_GENERATE) {
        family->id = genl_alloc_id(family);
        if (family->id < 0) {
            err = family->id;
            goto out_unlock;
        }
    } else {
        if (family->id >= GENL_ID_MIN && family->id < GENL_ID_GENERATE &&
            genl_id_to_family(family->id)) {
            err = -EADDRINUSE;
            goto out_unlock;
        }
    }

    if (family->n_attrs > 0) {
        family->attrs = kcalloc(family->n_attrs + 1, sizeof(*family->attrs), GFP_KERNEL);
        if (!family->attrs) {
            err = -ENOMEM;
            goto out_unlock;
        }
    }

    if (family->n_mcgrps > 0) {
        for (int i = 0; i < family->n_mcgrps; i++) {
            if (family->mcgrps[i].name[0] == '\0' || family->mcgrps[i].id == 0) {
                err = -EINVAL;
                goto out_free_attrs;
            }
        }
    }

    list_add_tail(&family->list, &genl_families);
    mutex_unlock(&genl_mutex);

    genl_notify_new_family(family);
    genl_notify_new_mcgrps(family);

    return 0;

out_free_attrs:
    kfree(family->attrs);
out_unlock:
    mutex_unlock(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family) {
    int err = 0;

    if (!family)
        return -EINVAL;

    if (family->version == 0 || family->hdrsize > GENL_MAX_ATTRLEN)
        return -EINVAL;

    if (family->id != 0 && family->id != GENL_ID_GENERATE) {
        if (family->id >= GENL_ID_CTRL || family->id < 0)
            return -EINVAL;
    }

    down_write(&genl_mutex);

    if (family->id == GENL_ID_GENERATE) {
        int i;
        for (i = GENL_ID_MIN; i < GENL_ID_CTRL; i++) {
            if (!genl_famTabIndex[i]) {
                family->id = i;
                break;
            }
        }
        if (i == GENL_ID_CTRL) {
            err = -EBUSY;
            goto out_unlock;
        }
    }

    if (genl_famTabIndex[family->id]) {
        err = -EEXIST;
        goto out_unlock;
    }

    if (family->n_attr) {
        family->attrbuf = kzalloc(family->n_attr * sizeof(void *), GFP_KERNEL);
        if (!family->attrbuf) {
            err = -ENOMEM;
            goto out_unlock;
        }
    }

    if (family->mcast_groups) {
        int i;
        for (i = 0; i < family->n_mcast_groups; i++) {
            if (family->mcast_groups[i].maxattr > family->n_attr) {
                err = -EINVAL;
                goto out_free_attrbuf;
            }
        }
    }

    genl_famTabIndex[family->id] = family;
    family->registered = 1;

    err = genl_notify_family(family);
    if (err < 0) {
        genl_unregister_family(family);
        goto out_free_attrbuf;
    }

    up_write(&genl_mutex);
    return 0;

out_free_attrbuf:
    kfree(family->attrbuf);
out_unlock:
    up_write(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family) {
    int err;

    if (!family)
        return -EINVAL;

    if (family->version == 0)
        family->version = 1;

    err = genl_validate_ops(family);
    if (err < 0)
        return err;

    mutex_lock(&genl_mutex);

    if (genl_find_family(family->name)) {
        mutex_unlock(&genl_mutex);
        return -EEXIST;
    }

    if (family->id == 0) {
        family->id = genl_get_free_id(family);
        if (family->id < 0) {
            mutex_unlock(&genl_mutex);
            return family->id;
        }
    }

    if (family->n_attrs > 0) {
        family->attr_policy = kzalloc(family->n_attrs *
                                       sizeof(struct nla_policy), GFP_KERNEL);
        if (!family->attr_policy) {
            mutex_unlock(&genl_mutex);
            return -ENOMEM;
        }
    }

    err = genl_register_multicast_groups(family);
    if (err < 0)
        goto err_out_free_attrs;

    err = genl_register_ops(family);
    if (err < 0)
        goto err_out_unregister_groups;

    list_add_tail(&family->list, &genl_families);

    mutex_unlock(&genl_mutex);

    genl_notify_family_event(family, GENL_FAMILY_NEW);

    return 0;

err_out_unregister_groups:
    genl_unregister_multicast_groups(family);
err_out_free_attrs:
    if (family->attr_policy)
        kfree(family->attr_policy);
    mutex_unlock(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family)
{
    int err;

    /* Validate operations */
    if (!family->version || !family->name || !family->ops || !family->n_ops)
        return -EINVAL;

    /* Lock generic netlink operations */
    mutex_lock(&genl_mutex);

    /* Check for duplicate family name */
    if (genl_find_family(family->name))
        goto out_unlock;

    /* Handle special reserved ID cases */
    if (family->id) {
        if (family->id >= GENL_ID_MIN && genl_families[family->id])
            goto out_unlock;
    }

    /* Allocate attributes memory if needed */
    if (family->n_attrs && !family->attr_type) {
        err = -ENOMEM;
        family->attr_type = kcalloc(family->n_attrs, sizeof(*family->attr_type), GFP_KERNEL);
        if (!family->attr_type)
            goto out_unlock;
    }

    /* Allocate family ID */
    if (!family->id) {
        for (family->id = 1; family->id < GENL_ID_MIN; family->id++) {
            if (!genl_families[family->id])
                break;
        }

        if (family->id >= GENL_ID_MIN)
            family->id = 0;
    }

    if (!family->id) {
        err = -ENOMEM;
        goto out_free_attrs;
    }

    /* Validate and assign multicast groups */
    if (family->n_multicast_groups > GENL_MAX_MC_GROUPS)
        family->n_multicast_groups = GENL_MAX_MC_GROUPS;

    for (int i = 0; i < family->n_multicast_groups; i++) {
        if (!family->mc_groups[i].name || !family->mc_groups[i].id)
            continue;

        if (family->mc_groups[i].id >= GENL_ID_MIN) {
            err = -EINVAL;
            goto out_free_id;
        }
    }

    /* Register the family */
    genl_families[family->id] = family;

    /* Notify about the new family */
    genl_notify_family_registered(family);

    mutex_unlock(&genl_mutex);
    return 0;

out_free_id:
    for (int i = 0; i < family->n_multicast_groups; i++)
        if (family->mc_groups[i].id == family->id)
            family->mc_groups[i].id = 0;
out_free_attrs:
    kfree(family->attr_type);
    family->attr_type = NULL;
out_unlock:
    mutex_unlock(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family)
{
    int err = 0;
    struct genl_family *tmp;
    struct genl_ops *ops;
    struct nlattr *tb[CTRL_ATTR_MAX + 1];
    struct nlmsghdr *n;
    struct sk_buff *skb;

    if (!family)
        return -EINVAL;

    if (!family->name || !family->version || !family->ops || !family->n_ops)
        return -EINVAL;

    genl_lock();

    if (genl_family_find(family->name))
        err = -EEXIST;
    if (!err && family->id >= GENL_ID_MIN && family->id < GENL_ID_MAX)
        err = -EINVAL;

    if (err) {
        genl_unlock();
        return err;
    }

    if (!family->maxattr) {
        family->maxattr = 0;
        for (int i = 0; i < family->n_ops; i++) {
            if (family->ops[i].maxattr > family->maxattr)
                family->maxattr = family->ops[i].maxattr;
        }
    }

    if (family->maxattr) {
        family->attrbuf = kcalloc(family->maxattr + 1, sizeof(void *), GFP_KERNEL);
        if (!family->attrbuf) {
            err = -ENOMEM;
            goto out;
        }
    }

    family->id = genl_get_id();
    if (family->id < 0) {
        err = family->id;
        goto out_free;
    }

    for (int i = 0; i < family->n_ops; i++) {
        ops = &family->ops[i];
        if (ops->policy) {
            err = ops->policy->check(family, ops, tb);
            if (err)
                goto out_free;
        }
    }

    err = genl_register_ops(family);
    if (err)
        goto out_free;

    for (int i = 0; i < family->n_multicast_groups; i++) {
        if (!family->mcgrps[i].name || !family->mcgrps[i].name[0])
            continue;

        err = genl_register_multicast_group(family, &family->mcgrps[i]);
        if (err)
            goto out_unregister_ops;
    }

    list_add_tail(&family->list, &genl_family_list);

    genl_unlock();

    n = genlmsg_put(skb, 0, 0, family, 0, CTRL_CMD_NEWFAMILY);
    if (!n) {
        err = -EINVAL;
        goto out_unregister;
    }

    nla_put(n, CTRL_ATTR_FAMILY_NAME, strlen(family->name), family->name);
    nla_put_u16(n, CTRL_ATTR_FAMILY_ID, family->id);
    nla_put_u16(n, CTRL_ATTR_VERSION, family->version);
    nla_put_string(n, CTRL_ATTR_HDRSZ, &family->hdrsize);
    nla_put_string(n, CTRL_ATTR_MAXATTR, &family->maxattr);

    for (int i = 0; i < family->n_ops; i++) {
        ops = &family->ops[i];
        nla_put_string(n, CTRL_ATTR_OPS, &ops->cmd);
        nla_put_string(n, CTRL_ATTR_OPS, &ops->policy);
    }

    for (int i = 0; i < family->n_multicast_groups; i++) {
        nla_put_string(n, CTRL_ATTR_MCAST_GRP_NAME, family->mcgrps[i].name);
        nla_put_string(n, CTRL_ATTR_MCAST_GRP_ID, &family->mcgrps[i].id);
    }

    n->nlmsg_len = nlmsg_end(skb, n);
    genl_notify(skb, NULL, 0, 0, GFP_KERNEL);

    return 0;

out_unregister:
    for (int i = 0; i < family->n_multicast_groups; i++)
        genl_unregister_multicast_group(family, &family->mcgrps[i]);
out_unregister_ops:
    genl_unregister_ops(family);
out_free:
    kfree(family->attrbuf);
    family->attrbuf = NULL;
out:
    genl_unlock();
    return err;
}
